// Package stack detects a workspace's application stack and generates a
// curated Dockerfile when the repository ships none (v3 spec §4.1).
//
// A user-supplied Dockerfile always wins: EnsureDockerfile is a no-op when one
// exists. The generated file is written into the workspace (and reported back
// so the agent can log it as an event), so the build stage needs no special
// casing and the user can inspect exactly what was generated.
package stack

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
)

// Provisioner generates a Dockerfile for a workspace without one.
type Provisioner struct{}

// EnsureDockerfile writes a curated Dockerfile into workspace when none
// exists. It returns the detected stack name and whether a file was written.
// An empty stack with no error means "no Dockerfile and no recognized stack" —
// callers should let the build fail with its own, familiar error.
func (Provisioner) EnsureDockerfile(_ context.Context, workspace string, port int) (stack string, generated bool, err error) {
	if _, statErr := os.Stat(filepath.Join(workspace, "Dockerfile")); statErr == nil {
		return "", false, nil
	} else if !os.IsNotExist(statErr) {
		return "", false, fmt.Errorf("inspect workspace: %w", statErr)
	}

	stack, err = detect(workspace)
	if err != nil || stack == "" {
		return stack, false, err
	}

	dockerfile, err := render(workspace, stack, port)
	if err != nil {
		return stack, false, err
	}
	if err := os.WriteFile(filepath.Join(workspace, "Dockerfile"), []byte(dockerfile), 0o644); err != nil { //nolint:gosec // world-readable build input
		return stack, false, fmt.Errorf("write generated Dockerfile: %w", err)
	}
	return stack, true, nil
}

// detect identifies the stack from marker files, most specific first.
func detect(workspace string) (string, error) {
	goMod, err := exists(workspace, "go.mod")
	if err != nil {
		return "", err
	}
	if goMod {
		return "go", nil
	}

	managePy, err := exists(workspace, "manage.py")
	if err != nil {
		return "", err
	}
	if managePy {
		return "django", nil
	}

	requirements, err := exists(workspace, "requirements.txt", "pyproject.toml")
	if err != nil {
		return "", err
	}
	if requirements {
		fastapi, err := exists(workspace, "main.py", filepath.Join("app", "main.py"))
		if err != nil {
			return "", err
		}
		if fastapi {
			return "fastapi", nil
		}
	}

	pkg, err := exists(workspace, "package.json")
	if err != nil {
		return "", err
	}
	if pkg {
		return "node", nil
	}

	index, err := exists(workspace, "index.html")
	if err != nil {
		return "", err
	}
	if index {
		return "static", nil
	}
	return "", nil
}

// goBuildTarget mirrors the bootstrap planner's convention: a main package
// under ./cmd/server, falling back to the module root.
func goBuildTarget(workspace string) string {
	if _, err := os.Stat(filepath.Join(workspace, "cmd", "server")); err == nil {
		return "./cmd/server"
	}
	return "."
}

// asgiApp picks the uvicorn target: main:app at the root, else app.main:app
// (the same layout the FastAPI bootstrap planner assumes).
func asgiApp(workspace string) string {
	if _, err := os.Stat(filepath.Join(workspace, "main.py")); err == nil {
		return "main:app"
	}
	return "app.main:app"
}

// wsgiModule finds the Django project directory (the one with settings.py)
// for the gunicorn target; defaults to config.wsgi like the bootstrap planner.
func wsgiModule(workspace string) string {
	entries, err := os.ReadDir(workspace)
	if err != nil {
		return "config.wsgi:application"
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		if _, err := os.Stat(filepath.Join(workspace, entry.Name(), "settings.py")); err == nil {
			return entry.Name() + ".wsgi:application"
		}
	}
	return "config.wsgi:application"
}

func exists(workspace string, names ...string) (bool, error) {
	for _, name := range names {
		if _, err := os.Stat(filepath.Join(workspace, name)); err == nil {
			return true, nil
		} else if !os.IsNotExist(err) {
			return false, fmt.Errorf("inspect %s: %w", name, err)
		}
	}
	return false, nil
}

const goTemplate = `# Generated by DeployDock (stack: go) — commit a Dockerfile to override.
FROM golang:1.26-alpine
WORKDIR /src
COPY . .
ENV CGO_ENABLED=0 PORT=%d
RUN go build -o /out/app %s
CMD ["/out/app"]
`

const nodeTemplate = `# Generated by DeployDock (stack: node) — commit a Dockerfile to override.
# The app must listen on $PORT, which DeployDock injects.
FROM node:22-alpine
WORKDIR /app
COPY package*.json ./
RUN npm install --omit=dev
COPY . .
ENV PORT=%d
EXPOSE %d
CMD ["npm", "start"]
`

const fastapiTemplate = `# Generated by DeployDock (stack: fastapi) — commit a Dockerfile to override.
FROM python:3.12-slim
WORKDIR /app
COPY requirements.txt ./
RUN pip install --no-cache-dir -r requirements.txt
COPY . .
EXPOSE %d
CMD ["uvicorn", "%s", "--host", "0.0.0.0", "--port", "%d"]
`

const djangoTemplate = `# Generated by DeployDock (stack: django) — commit a Dockerfile to override.
FROM python:3.12-slim
WORKDIR /app
COPY requirements.txt ./
RUN pip install --no-cache-dir -r requirements.txt gunicorn
COPY . .
EXPOSE %d
CMD ["sh", "-c", "python manage.py migrate --noinput && exec gunicorn %s --bind 0.0.0.0:%d --workers 2"]
`

// staticTemplate: the nginx image envsubts /etc/nginx/templates/*.template
// into conf.d, so ${PORT} reaches runtime config from ENV and the single
// quotes keep $uri literal through the build.
const staticTemplate = `# Generated by DeployDock (stack: static) — commit a Dockerfile to override.
FROM nginx:1.27-alpine
COPY . /usr/share/nginx/html
RUN printf 'server {\n  listen ${PORT};\n  location / {\n    root /usr/share/nginx/html;\n    index index.html;\n    try_files $uri $uri/ /index.html;\n  }\n}\n' > /etc/nginx/templates/default.conf.template
ENV PORT=%d
`

func render(workspace, stack string, port int) (string, error) {
	switch stack {
	case "go":
		return fmt.Sprintf(goTemplate, port, goBuildTarget(workspace)), nil
	case "node":
		return fmt.Sprintf(nodeTemplate, port, port), nil
	case "fastapi":
		return fmt.Sprintf(fastapiTemplate, port, asgiApp(workspace), port), nil
	case "django":
		return fmt.Sprintf(djangoTemplate, port, wsgiModule(workspace), port), nil
	case "static":
		return fmt.Sprintf(staticTemplate, port), nil
	default:
		return "", fmt.Errorf("no curated Dockerfile template for stack %q", stack)
	}
}
